CS = "Lamborghini Centro Stile"


def E(id, family, name, kind, year, end, body, engine, eng, cv, units, designer, cats, wiki=None, note=""):
    return dict(id=id, family=family, name=name, kind=kind, year=year, end=end, body=body,
                engine=engine, eng=eng, cv=cv, units=units, designer=designer,
                cats=cats if isinstance(cats, list) else [cats], wiki=wiki, note=note)


